#!/usr/bin/env python3
"""Write detailed release notes for a stackq release to stdout.

    release_notes.py --repo OWNER/NAME --tag v1.2.3 [--prev v1.2.2] \
        [--checksums dist/checksums.txt]

Walks the first-parent history since --prev (everything for a first release),
looks up each merged PR (title, author, size, description) through the GitHub
API, and lists direct commits too. GITHUB_TOKEN is used when set.
"""
import argparse
import json
import os
import re
import subprocess
import sys
import urllib.request

MAX_BODY = 4000
FOOTERS = ("🤖 Generated with", "https://claude.ai/code/session", "_Generated by [Claude Code]")


def git(*args):
    return subprocess.run(["git", *args], check=True, capture_output=True, text=True).stdout


def api(path):
    req = urllib.request.Request("https://api.github.com/" + path, headers={"Accept": "application/vnd.github+json"})
    if os.environ.get("GITHUB_TOKEN"):
        req.add_header("Authorization", "Bearer " + os.environ["GITHUB_TOKEN"])
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


def clean_body(body):
    lines = [l.rstrip() for l in (body or "").replace("\r", "").split("\n")]
    lines = [l for l in lines if not l.startswith(FOOTERS)]
    # Demote headings: the release page has its own structure.
    lines = [re.sub(r"^#+\s+(.*)$", r"**\1**", l) for l in lines]
    text = "\n".join(lines).strip()
    while text.endswith("---"):  # the rule that sat above a stripped footer
        text = text[:-3].rstrip()
    if len(text) > MAX_BODY:
        text = text[:MAX_BODY].rstrip() + "\n\n_(description shortened; see the PR)_"
    return text


def history(prev):
    """First-parent entries since prev as (sha, subject, body, pr number or None)."""
    rng = f"{prev}..HEAD" if prev else "HEAD"
    out = git("log", "--first-parent", "--format=%H%x1f%s%x1f%b%x1e", rng)
    entries = []
    for rec in out.split("\x1e"):
        if not rec.strip():  # the text after the last separator
            continue
        sha, subject, body = (rec.strip("\n").split("\x1f") + ["", ""])[:3]
        m = re.match(r"Merge pull request #(\d+)", subject) or re.search(r"\(#(\d+)\)$", subject)
        entries.append((sha, subject, body.strip(), int(m.group(1)) if m else None))
    return entries


def sizes(items):
    a = sum(i["additions"] for i in items)
    d = sum(i["deletions"] for i in items)
    f = sum(i["changed_files"] for i in items)
    return a, d, f


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True)
    ap.add_argument("--tag", required=True)
    ap.add_argument("--prev", default="")
    ap.add_argument("--checksums", default="")
    ap.add_argument("--bump", default="")
    o = ap.parse_args()

    prs, direct = [], []
    for sha, subject, body, n in history(o.prev):
        if n is None:
            direct.append((sha, subject))
            continue
        try:
            prs.append(api(f"repos/{o.repo}/pulls/{n}"))
        except Exception as e:  # keep the release going if one lookup fails
            print(f"warning: PR #{n}: {e}", file=sys.stderr)
            prs.append({"number": n, "title": subject, "body": body, "user": {"login": "unknown"},
                        "additions": 0, "deletions": 0, "changed_files": 0, "labels": [],
                        "html_url": f"https://github.com/{o.repo}/pull/{n}"})

    print(f"## stackq {o.tag}\n")
    a, d, f = sizes(prs)
    since = f"since {o.prev}" if o.prev else "(first release)"
    summary = f"{len(prs)} merged PR{'s' if len(prs) != 1 else ''}"
    if direct:
        summary += f" and {len(direct)} direct commit{'s' if len(direct) != 1 else ''}"
    print(f"{summary} {since}: {f} files changed, **+{a} / −{d}** lines.")
    if o.bump:
        print(f"\nVersion bump: {o.bump}.")
    print()

    print("### What changed\n")
    if not prs and not direct:
        print("No changes.\n")
    for p in prs:
        labels = ", ".join(l["name"] for l in p.get("labels", []))
        meta = f"@{p['user']['login']} · +{p['additions']} / −{p['deletions']} · {p['changed_files']} files"
        if labels:
            meta += f" · {labels}"
        print(f"#### {p['title']} ([#{p['number']}]({p['html_url']}))\n")
        print(f"_{meta}_\n")
        body = clean_body(p.get("body"))
        if body:
            print(body + "\n")
    if direct:
        print("#### Direct commits\n")
        for sha, subject in direct:
            print(f"- {subject} ([`{sha[:7]}`](https://github.com/{o.repo}/commit/{sha}))")
        print()

    print("### Download\n")
    print("Binaries are attached below. The names carry no version, so "
          f"`https://github.com/{o.repo}/releases/download/{o.tag}/<name>` is stable.\n")
    if o.checksums and os.path.exists(o.checksums):
        print("| File | SHA-256 |\n| --- | --- |")
        for line in open(o.checksums):
            parts = line.split()
            if len(parts) == 2:
                print(f"| `{parts[1]}` | `{parts[0]}` |")
        print()
    print("```sh")
    print(f"curl -fsSLO https://github.com/{o.repo}/releases/download/{o.tag}/stackq_linux_amd64")
    print(f"curl -fsSLO https://github.com/{o.repo}/releases/download/{o.tag}/checksums.txt")
    print("sha256sum -c --ignore-missing checksums.txt && chmod +x stackq_linux_amd64")
    print("```\n")

    print("### Use it in GitHub Actions\n")
    print("```yaml")
    print(f"- uses: {o.repo}@{o.tag.split('.')[0]}   # follows the newest {o.tag.split('.')[0]}.x release")
    print("  with:")
    print(f"    version: {o.tag}               # pin this exact binary")
    print("    token: ${{ github.token }}")
    print("```\n")

    if o.prev:
        print(f"**Full changelog**: https://github.com/{o.repo}/compare/{o.prev}...{o.tag}")
    else:
        print(f"**Full changelog**: https://github.com/{o.repo}/commits/{o.tag}")


if __name__ == "__main__":
    main()
